<?php
/**
 * Nahian POS Extra Add-on Delete Handler
 *
 * @package NRTOK_POS
 * @since   1.0.0
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

if ( isset( $_GET['del_extra'] ) ) {
	if ( ! current_user_can( 'manage_options' ) ) {
		wp_die( esc_html__( 'You do not have sufficient permissions to perform this action.', 'nahian-restaurant-ordering-system' ) );
	}

	$extra_id = absint( $_GET['del_extra'] );
	if ( $extra_id > 0 ) {
		// Verify CSRF nonce generated by wp_nonce_url() in extra-list.php & extra-view.php.
		check_admin_referer( 'nrtok_delete_extra_' . $extra_id );

		global $wpdb;
		$t_extras  = $wpdb->prefix . 'nrtok_extras';
		$t_menu    = $wpdb->prefix . 'nrtok_menu';
		$svg_check = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';

		// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
		if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $t_extras ) ) === $t_extras ) {
			// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
			$deleted = $wpdb->delete(
				$t_extras,
				array( 'id' => $extra_id ),
				array( '%d' )
			);

			if ( false !== $deleted && $deleted > 0 ) {
				// Clean up deleted extra ID from any attached menu dishes.
				// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
				if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $t_menu ) ) === $t_menu ) {
					// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
					$menu_rows = $wpdb->get_results( $wpdb->prepare( 'SELECT id, extras FROM %i WHERE extras IS NOT NULL AND extras != %s', $t_menu, '' ) );
					if ( is_array( $menu_rows ) ) {
						foreach ( $menu_rows as $m_row ) {
							$ids = json_decode( $m_row->extras, true );
							if ( is_array( $ids ) ) {
								$clean_ids = array_values(
									array_filter(
										array_map( 'absint', $ids ),
										function ( $id ) use ( $extra_id ) {
											return $id > 0 && $id !== $extra_id;
										}
									)
								);
								if ( count( $clean_ids ) !== count( $ids ) ) {
									// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
									$wpdb->update(
										$t_menu,
										array( 'extras' => wp_json_encode( $clean_ids ) ),
										array( 'id' => absint( $m_row->id ) ),
										array( '%s' ),
										array( '%d' )
									);
								}
							}
						}
					}
				}

				echo '<div class="nrtok-alert nrtok-ex-alert-flex">' . $svg_check . '<span>' . sprintf( // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
					/* translators: %d: extra add-on ID */
					esc_html__( 'Extra #%d deleted successfully!', 'nahian-restaurant-ordering-system' ),
					absint( $extra_id )
				) . '</span></div>';
			} else {
				echo '<div class="nrtok-alert" style="background:#fef2f2; border-color:#fecaca; color:#b91c1c;">' . esc_html__( 'Extra add-on could not be deleted or was already removed.', 'nahian-restaurant-ordering-system' ) . '</div>';
			}
		}
	}
}